import csv
import json
import math
from collections import defaultdict
from datetime import datetime

# ── Load data ──────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for r in reader:
        d = r['Date'].strip()
        price = float(r['Crude_Oil_Price'].strip())
        if d and price:
            rows.append({'date': d, 'price': price})

rows.sort(key=lambda x: x['date'])
prices = [r['price'] for r in rows]
dates = [r['date'] for r in rows]
n = len(rows)

# ── Basic stats ────────────────────────────────────────────────────────
min_price = min(prices)
max_price = max(prices)
min_idx = prices.index(min_price)
max_idx = prices.index(max_price)
mean_price = sum(prices) / n

# Sort for median & percentiles
sorted_prices = sorted(prices)
median_price = sorted_prices[n // 2] if n % 2 else (sorted_prices[n//2 - 1] + sorted_prices[n//2]) / 2

def percentile(data, p):
    k = (len(data) - 1) * p / 100
    f = int(k)
    c = k - f
    if f + 1 < len(data):
        return data[f] + c * (data[f+1] - data[f])
    return data[f]

p10 = percentile(sorted_prices, 10)
p25 = percentile(sorted_prices, 25)
p75 = percentile(sorted_prices, 75)
p90 = percentile(sorted_prices, 90)

# Standard deviation
mean_p = mean_price
variance = sum((x - mean_p)**2 for x in prices) / n
std_dev = math.sqrt(variance)

# ── Overall price range ────────────────────────────────────────────────
price_range = max_price - min_price

# ── CAGR ───────────────────────────────────────────────────────────────
first_date = dates[0]
last_date = dates[-1]
first_price = prices[0]
last_price = prices[-1]

d1 = datetime.strptime(first_date, '%Y-%m-%d')
d2 = datetime.strptime(last_date, '%Y-%m-%d')
years_elapsed = (d2 - d1).days / 365.25
cagr = ((last_price / first_price) ** (1 / years_elapsed) - 1) * 100

# ── Month-over-month changes ───────────────────────────────────────────
mom_abs = []
mom_pct = []
mom_data = []
for i in range(1, n):
    abs_chg = prices[i] - prices[i-1]
    pct_chg = (prices[i] - prices[i-1]) / prices[i-1] * 100
    mom_abs.append(abs(abs_chg))
    mom_pct.append(abs(pct_chg))
    mom_data.append({
        'date': dates[i],
        'prev_date': dates[i-1],
        'abs_change': abs_chg,
        'pct_change': pct_chg
    })

max_mom_abs = max(mom_data, key=lambda x: abs(x['abs_change']))
max_mom_pct = max(mom_data, key=lambda x: abs(x['pct_change']))

# ── Year-over-year changes ─────────────────────────────────────────────
yoy_data = []
for i in range(12, n):
    pct_chg = (prices[i] - prices[i-12]) / prices[i-12] * 100
    yoy_data.append({
        'date': dates[i],
        'pct_change': pct_chg
    })

max_yoy_inc = max(yoy_data, key=lambda x: x['pct_change'])
max_yoy_dec = min(yoy_data, key=lambda x: x['pct_change'])

# ── Decade analysis ────────────────────────────────────────────────────
def get_decade(date_str):
    return (int(date_str[:4]) // 10) * 10

decade_groups = defaultdict(list)
decade_dates = defaultdict(list)
for r in rows:
    dec = get_decade(r['date'])
    decade_groups[dec].append(r['price'])
    decade_dates[dec].append(r['date'])

decade_stats = {}
for dec in sorted(decade_groups.keys()):
    vals = decade_groups[dec]
    dts = decade_dates[dec]
    if len(vals) < 2:
        continue
    mean_v = sum(vals) / len(vals)
    var_v = sum((x - mean_v)**2 for x in vals) / len(vals)
    std_v = math.sqrt(var_v)
    decade_stats[dec] = {
        'mean': mean_v,
        'std': std_v,
        'min': min(vals),
        'max': max(vals),
        'range': max(vals) - min(vals),
        'first_price': vals[0],
        'last_price': vals[-1],
        'start_date': dts[0],
        'end_date': dts[-1],
        'count': len(vals),
        'cv': (std_v / mean_v * 100) if mean_v else 0
    }

highest_avg_decade = max(decade_stats, key=lambda d: decade_stats[d]['mean'])

# ── Top 10 MoM moves ──────────────────────────────────────────────────
top_mom_abs = sorted(mom_data, key=lambda x: abs(x['pct_change']), reverse=True)[:10]

