# Compute event shocks programmatically
def find_shock(start_d, end_d, label):
    try:
        si = dates.index(start_d)
        ei = dates.index(end_d)
        ps = prices[si]
        pe = prices[ei]
        chg = pe - ps
        pct = (pe/ps - 1) * 100
        # Find max MoM in that window
        window_mom = [m for m in mom_data if start_d <= m['date'] <= end_d]
        max_m = max(window_mom, key=lambda x: abs(x['pct_change'])) if window_mom else None
        months = ei - si
        return {
            'label': label, 'start': start_d, 'end': end_d,
            'price_start': ps, 'price_end': pe, 'change': chg,
            'change_pct': pct, 'months': months,
            'peak_mom': max_m['pct_change'] if max_m else 0,
            'peak_mom_date': max_m['date'] if max_m else 'N/A'
        }
    except (ValueError, IndexError):
        return None

